'use strict';
const travelerMapExpanded=new Set();
function travelerNextAction(r){const holds=openIssues(r);if(holds.length)return {title:'Resolve the hold',text:holds.map(e=>e.title+' — '+e.owner).join('; ')+'. Record the evidence and resolution before advancing.',tab:'exceptions',action:'Review exceptions'};if(r.stage===4)return {title:'Journey complete',text:r.ack?'The simulated inventory handoff is acknowledged. Review the event history for the record.':'This return closed with an approved '+r.disposition+' disposition. No inventory handoff was performed.',tab:'history',action:'View event history'};if(r.stage===0)return {title:'Ready for inspection handoff',text:'Review the receipt identifiers and ownership, then move the return to inspection.',tab:'details',action:'Review receiving'};if(r.stage===1)return {title:r.inspected?'Inspection recorded':'Inspection required',text:r.inspected?'Review the findings before moving to disposition.':'Record the observed condition and inspection notes before advancing.',tab:'details',action:'Review inspection'};if(r.stage===2)return {title:r.approved?'Disposition approved':'Decision and approval required',text:r.approved?'Approved outcome: '+r.disposition+'. Review the decision before advancing.':'Select an outcome, record the rationale, and confirm supervisor approval.',tab:'details',action:'Review disposition'};return {title:'Ready for simulated handoff',text:'Review the approved resale record before simulating the inventory acknowledgment and closing the traveler.',tab:'details',action:'Review handoff'};}
function travelerMiniMap(r){const hold=openIssues(r).length>0,station=hold?5:r.stage===4?4:[0,1,2,3][r.stage];const zones=[['Receiving',30,42],['Inspection',200,42],['Disposition',370,42],['Inventory',115,132],['Closed / exit',285,132],['Exception hold',455,132]];return `<svg class="rv-map" viewBox="0 0 625 225" role="img" aria-label="Illustrative workflow location for ${esc(r.id)}: ${hold?'exception hold':STAGES[r.stage]}"><defs><pattern id="rv-floor-grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M 25 0 L 0 0 0 25" fill="none" stroke="#dce5df" stroke-width="1"/></pattern></defs><rect x="6" y="6" width="613" height="213" rx="12" fill="#f1f5f2"/><rect x="6" y="6" width="613" height="213" rx="12" fill="url(#rv-floor-grid)"/><path d="M95 82H435V112H180V172H350" fill="none" stroke="#9bbaac" stroke-width="3" stroke-dasharray="7 6"/>${zones.map(([name,x,y],i)=>{const active=station===i,color=i===5?'#be633d':'#068667';return `<g><path d="M${x} ${y+12}l12 -10h124v48l-12 10H${x}z" fill="${active?color:'#d5dfd9'}" opacity="${active?1:.8}"/><rect x="${x}" y="${y+12}" width="124" height="48" rx="4" fill="${active?(i===5?'#fff0dc':'#d7f4e7'):'#fff'}" stroke="${active?color:'#c6d3cb'}" stroke-width="${active?2:1}"/><text x="${x+62}" y="${y+40}" text-anchor="middle" font-size="12" font-family="Arial,sans-serif" fill="#244639" font-weight="${active?700:400}">${name}</text>${active?`<circle cx="${x+114}" cy="${y+15}" r="7" fill="${color}" stroke="white" stroke-width="2"/>`:''}</g>`;}).join('')}</svg>`;}
function travelerVisual(r){const holds=openIssues(r),next=travelerNextAction(r),nonResale=r.stage===4&&!r.ack&&r.disposition!=='Resale';const steps=['Receiving','Inspection','Disposition','Inventory handoff','Closed'];return `<section class="rv-journey" aria-label="Return journey"><div class="rv-journey-heading"><div><small>Return journey</small><h2>${r.stage===4?'Completed':holds.length?'On hold at '+STAGES[r.stage]:STAGES[r.stage]}</h2></div>${statusTag(r)}</div><ol class="rv-journey-steps">${steps.map((name,i)=>{const skipped=i===3&&nonResale,done=i<r.stage&&!skipped,current=i===r.stage;return `<li class="${done?'done':current?'current':''} ${current&&holds.length?'blocked':''} ${skipped?'skipped':''}" ${current?'aria-current="step"':''}><span class="rv-step-dot">${done?'✓':skipped?'–':current&&holds.length?'!':i+1}</span><strong>${name}</strong><small>${skipped?'Not required':done?'Completed':current?(holds.length?'Blocked':'Current'):'Pending'}</small></li>`;}).join('')}</ol><div class="rv-next ${holds.length?'on-hold':''}"><span class="rv-next-icon">${holds.length?'⚠':r.stage===4?'✓':'→'}</span><div><strong>${esc(next.title)}</strong><p>${esc(next.text)}</p></div><button class="secondary" id="rv-next-action">${next.action}</button></div><details class="rv-location" ${travelerMapExpanded.has(r.id)?'open':''}><summary>Show workflow location <span>${holds.length?'Exception hold':STAGES[r.stage]}</span></summary>${travelerMiniMap(r)}<p>Illustrative location derived from this traveler’s stage and holds. No physical tracking is connected.</p></details></section>`;}
const drawBeforeVisual=drawRecord;
drawRecord=function(){drawBeforeVisual();const r=records.find(r=>r.id===selected);if(!r)return;const old=$('#drawer .detail-stages');if(old)old.outerHTML=travelerVisual(r);const next=travelerNextAction(r);$('#rv-next-action').onclick=()=>{tab=next.tab;drawRecord();$('#detail-content').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});};$('#drawer .rv-location').ontoggle=e=>{if(e.target.open)travelerMapExpanded.add(r.id);else travelerMapExpanded.delete(r.id);};};

// The full warehouse is a scenario sandbox. Actual return state stays in travelers.
twinState.mode='scenario';
function scenarioSummary(){const node=$('.twin-summary');if(page!=='twin'||!node||!twinState.result)return;const s=twinState.result.scenario;node.innerHTML=[['⇥','Completed in 8h',s.completed.toFixed(1)],['◷','Remaining after 8h',s.wip.toFixed(1)],['↶','Mean turnaround · all arrivals',s.eventualTurnaround.toFixed(0)+' min']].map(([icon,label,n])=>`<div><span class="summary-symbol">${icon}</span><span>${label}<strong>${n}</strong></span></div>`).join('');}
const comparisonBeforeSummary=renderComparison;renderComparison=function(){comparisonBeforeSummary();scenarioSummary();};
const renderBeforeSimulationOnly=render;
render=function(){if((location.hash.slice(1)||'overview')==='twin')twinState.mode='scenario';renderBeforeSimulationOnly();if(page==='twin'){const mode=$('.twin-mode');if(mode)mode.remove();$('.twin-heading').classList.add('simulation-only');$('.twin-heading p').textContent='Change the conditions and compare their impact on warehouse flow.';scenarioSummary();}};
render();
